"use client";

import * as React from "react";
import { ArrowUp, CircleAlert, X } from "lucide-react";
import { DropZoneFileRow } from "./drop-zone-file-row";
import type { DropZoneProps } from "./drop-zone-types";
import { selectionHint } from "./drop-zone-utils";
import { useDropZone } from "./use-drop-zone";
import { TextMorph } from "./text-morph";
import { INTERACTION_FOCUS } from "./imported-ui-interaction-motion";

export type {
  DropZoneStatus,
  DropZoneFile,
  DropZoneUpload,
  DropZoneRejection,
  DropZoneHandle,
  DropZoneProps,
} from "./drop-zone-types";
export { formatBytes } from "./drop-zone-utils";

const carriesFiles = (data: DataTransfer) =>
  Array.from(data.types).includes("Files");

export function DropZone({
  onUpload,
  onFilesChange,
  onFilesRejected,
  accept,
  maxSize,
  maxFiles,
  multiple = true,
  title = "Drop files here",
  hint,
  disabled = false,
  ref,
  className = "",
  onPaste,
  ...props
}: DropZoneProps) {
  const input = React.useRef<HTMLInputElement>(null);
  const area = React.useRef<HTMLButtonElement>(null);
  const depth = React.useRef(0);
  const [dragging, setDragging] = React.useState(false);
  const id = React.useId();
  const {
    rows,
    rejections,
    announcement,
    add,
    remove,
    retry,
    dismissRejections,
  } = useDropZone({
    onUpload,
    onFilesChange,
    onFilesRejected,
    accept,
    maxSize,
    maxFiles,
    multiple,
    disabled,
  });
  const description =
    hint ?? selectionHint(accept, maxSize, multiple ? maxFiles : 1);

  const cancel = React.useCallback(() => {
    depth.current = 0;
    setDragging(false);
  }, []);
  const browse = React.useCallback(() => {
    if (!disabled) input.current?.click();
  }, [disabled]);
  const contains = React.useCallback((x: number, y: number) => {
    const rect = area.current?.getBoundingClientRect();
    return (
      !!rect &&
      rect.width > 0 &&
      rect.height > 0 &&
      x >= rect.left &&
      x <= rect.right &&
      y >= rect.top &&
      y <= rect.bottom
    );
  }, []);

  const [seenDisabled, setSeenDisabled] = React.useState(disabled);
  if (disabled !== seenDisabled) {
    setSeenDisabled(disabled);
    if (disabled && dragging) setDragging(false);
  }
  React.useEffect(() => {
    if (disabled) depth.current = 0;
  }, [disabled]);
  React.useImperativeHandle(
    ref,
    () => ({
      browse,
      cancel,
      drag: (x, y) => {
        const inside = !disabled && contains(x, y);
        setDragging(inside);
        return inside;
      },
      drop: (files, at) => {
        cancel();
        if (!at || contains(at.x, at.y)) add(files);
      },
    }),
    [browse, cancel, disabled, contains, add],
  );

  return (
    <div
      {...props}
      className={`@container relative w-full min-w-0 text-foreground ${className}`}
      onPaste={(event) => {
        onPaste?.(event);
        if (event.defaultPrevented || disabled) return;
        const files = Array.from(event.clipboardData.files);
        if (files.length) {
          event.preventDefault();
          cancel();
          add(files);
        }
      }}
    >
      <button
        ref={area}
        type="button"
        disabled={disabled}
        onClick={browse}
        aria-label={`Browse ${multiple ? "files" : "file"}`}
        aria-describedby={`${id}-title ${id}-hint`}
        data-drop-zone=""
        data-dragging={dragging || undefined}
        aria-disabled={disabled || undefined}
        onDragEnter={(event) => {
          if (!carriesFiles(event.dataTransfer)) return;
          event.preventDefault();
          if (!disabled) {
            depth.current++;
            setDragging(true);
          }
        }}
        onDragOver={(event) => {
          if (!carriesFiles(event.dataTransfer)) return;
          event.preventDefault();
          event.dataTransfer.dropEffect = disabled ? "none" : "copy";
          if (!disabled) setDragging(true);
        }}
        onDragLeave={(event) => {
          event.preventDefault();
          depth.current = Math.max(0, depth.current - 1);
          if (!depth.current) setDragging(false);
        }}
        onDrop={(event) => {
          event.preventDefault();
          cancel();
          add(Array.from(event.dataTransfer.files));
        }}
        onDragEnd={cancel}
        className={`relative flex min-h-[152px] w-full cursor-pointer flex-col items-center justify-center gap-3 rounded-[18px] border px-5 py-5 text-center transition-colors duration-200 disabled:cursor-default disabled:opacity-55 motion-reduce:transition-none @md:min-h-[176px] ${INTERACTION_FOCUS} ${
          dragging ? "border-primary bg-primary/5" : "border-border bg-muted/45"
        }`}
      >
        <span
          className={`relative flex size-9 shrink-0 items-center justify-center rounded-full border bg-background transition-colors duration-200 motion-reduce:transition-none ${dragging ? "border-primary/30 text-primary" : "border-border text-muted-foreground"}`}
        >
          <ArrowUp className="size-4" strokeWidth={1.75} aria-hidden="true" />
        </span>
        <span className="relative flex max-w-full flex-col items-center gap-1">
          <span
            id={`${id}-title`}
            className="text-[13.5px] font-medium tracking-[-0.01em]"
          >
            <TextMorph>{dragging ? "Release to add" : title}</TextMorph>
          </span>
          <span
            id={`${id}-hint`}
            className="text-balance text-[12px] leading-relaxed text-muted-foreground"
          >
            <span className="whitespace-nowrap">
              <span className="text-foreground underline decoration-border underline-offset-[3px]">
                Browse
              </span>{" "}
              or paste ·
            </span>{" "}
            {description}
          </span>
        </span>
      </button>
      <input
        ref={input}
        type="file"
        hidden
        disabled={disabled}
        multiple={multiple}
        accept={accept}
        onChange={(event) => {
          const files = Array.from(event.currentTarget.files ?? []);
          event.currentTarget.value = "";
          cancel();
          add(files);
        }}
      />

      {rejections.length > 0 && (
        <div
          role="alert"
          className="mt-2 flex items-start gap-2 text-red-600 dark:text-red-400"
        >
          <CircleAlert className="mt-2 size-3.5 shrink-0" aria-hidden="true" />
          <div className="min-w-0 flex-1 py-1.5 text-[12px] leading-relaxed [overflow-wrap:anywhere]">
            {rejections.slice(0, 3).map((rejection, index) => (
              <p key={index} className="break-words">
                <span className="font-medium">{rejection.file.name}</span> —{" "}
                {rejection.reason}
              </p>
            ))}
            {rejections.length > 3 && (
              <p className="mt-1">
                {rejections.length - 3} more files skipped.
              </p>
            )}
          </div>
          <button
            type="button"
            aria-label="Dismiss file errors"
            onClick={dismissRejections}
            className={`flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full hover:bg-muted ${INTERACTION_FOCUS}`}
          >
            <X className="size-3.5" aria-hidden="true" />
          </button>
        </div>
      )}

      {rows.length > 0 && (
        <ul aria-label="Files" className="mt-3 min-w-0">
          {rows.map((row) => (
            <DropZoneFileRow
              key={row.id}
              row={row}
              disabled={disabled}
              onRemove={() => remove(row.id)}
              onRetry={() => retry(row.id)}
            />
          ))}
        </ul>
      )}
      <p
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {announcement}
      </p>
    </div>
  );
}

"use client";

import {
  File as FileIcon,
  FileImage,
  FileText,
  RotateCcw,
  X,
} from "lucide-react";
import type { DropZoneFile } from "./drop-zone-types";
import { formatBytes } from "./drop-zone-utils";
import { DropZoneStatusMark } from "./drop-zone-status";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import { INTERACTION_FOCUS } from "./imported-ui-interaction-motion";

const action = `flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:cursor-default disabled:opacity-40 motion-reduce:transition-none ${INTERACTION_FOCUS}`;

export function DropZoneFileRow({
  row,
  disabled,
  onRemove,
  onRetry,
}: {
  row: DropZoneFile;
  disabled: boolean;
  onRemove: () => void;
  onRetry: () => void;
}) {
  const { file, status, progress, error } = row;
  const Icon = file.type.startsWith("image/")
    ? FileImage
    : file.type === "application/pdf" || file.type.startsWith("text/")
      ? FileText
      : FileIcon;
  const uploading = status === "uploading";
  const errorId = `${row.id}-error`;

  return (
    <li
      className={`relative min-w-0 border-b ${status === "error" ? "border-destructive" : "border-border"}`}
      aria-describedby={error ? errorId : undefined}
    >
      <div className="flex h-11 min-w-0 items-center gap-2 sm:gap-3">
        <span className="flex min-w-0 flex-1 items-center gap-2.5 text-[13px]">
          <Icon
            className="size-4 shrink-0 text-muted-foreground"
            strokeWidth={1.75}
            aria-hidden="true"
          />
          <span className="truncate" title={file.name}>
            {file.name}
          </span>
        </span>
        <span className="flex shrink-0 items-center gap-1 text-[12px] tabular-nums text-muted-foreground">
          <span
            className={`whitespace-nowrap ${status === "error" ? "text-red-600 dark:text-red-400" : ""}`}
          >
            {status === "error" ? (
              <TextMorph>Failed</TextMorph>
            ) : (
              <>
                {formatBytes(file.size)}
                {uploading && (
                  <span className="ml-1">
                    <span aria-hidden="true">· </span>
                    <NumberRoll
                      value={Math.floor(progress * 100)}
                      suffix="%"
                      duration={400}
                    />
                  </span>
                )}
              </>
            )}
          </span>
          <DropZoneStatusMark status={status} progress={progress} />
          <span className="sr-only">
            {status === "done"
              ? "Uploaded"
              : status === "ready"
                ? "Ready"
                : uploading
                  ? "Uploading"
                  : "Upload failed"}
          </span>
          {status === "error" && (
            <button
              type="button"
              aria-label={`Retry upload of ${file.name}`}
              title="Retry upload"
              disabled={disabled}
              onClick={onRetry}
              className={action}
            >
              <RotateCcw
                className="size-3.5"
                strokeWidth={1.75}
                aria-hidden="true"
              />
            </button>
          )}
          <button
            type="button"
            aria-label={`${uploading ? "Cancel upload of" : "Remove"} ${file.name}`}
            title={uploading ? "Cancel upload" : "Remove file"}
            disabled={disabled}
            onClick={onRemove}
            className={action}
          >
            <X className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
          </button>
        </span>
      </div>
      {error && (
        <p
          id={errorId}
          className="pb-2.5 pl-[26px] pr-1 text-[11.5px] leading-relaxed text-red-600 [overflow-wrap:anywhere] dark:text-red-400"
        >
          {error}
        </p>
      )}
      {uploading && (
        <span
          role="progressbar"
          aria-label={`Upload progress for ${file.name}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.floor(progress * 100)}
          className="pointer-events-none absolute inset-x-0 -bottom-px h-px"
        >
          <span
            className="block h-full origin-left bg-primary transition-transform duration-200 motion-reduce:transition-none"
            style={{ transform: `scaleX(${progress})` }}
          />
        </span>
      )}
    </li>
  );
}

import type * as React from "react";

export type DropZoneStatus = "ready" | "uploading" | "done" | "error";

export interface DropZoneFile {
  id: string;
  file: File;
  status: DropZoneStatus;
  /** A fraction from 0 to 1. */
  progress: number;
  error?: string;
}

export type DropZoneUpload = (
  file: File,
  context: { progress: (fraction: number) => void; signal: AbortSignal },
) => void | Promise<void>;

export interface DropZoneRejection {
  file: File;
  code: "type" | "size" | "count" | "duplicate";
  reason: string;
}

export interface DropZoneHandle {
  /** Tracks a drag from your app. Only coordinates inside the drop area return true. */
  drag: (clientX: number, clientY: number, types?: string[]) => boolean;
  cancel: () => void;
  /** Adds files from your app; optional coordinates must be inside the drop area. */
  drop: (files: File[], at?: { x: number; y: number }) => void;
  browse: () => void;
}

export interface DropZoneProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onDrop" | "title"
> {
  /** Resolve when uploaded, throw to offer Retry, and honour the abort signal. */
  onUpload?: DropZoneUpload;
  /** Current selection after adding, replacing or removing files. */
  onFilesChange?: (files: File[]) => void;
  onFilesRejected?: (rejections: DropZoneRejection[]) => void;
  /** Native input syntax: MIME types, wildcards or extensions, e.g. "image/*,.pdf". */
  accept?: string;
  /** Maximum size of each file in bytes. */
  maxSize?: number;
  maxFiles?: number;
  /** false replaces the current file when a valid new file is selected. */
  multiple?: boolean;
  title?: string;
  hint?: string;
  disabled?: boolean;
  ref?: React.Ref<DropZoneHandle>;
}

import type { DropZoneRejection } from "./drop-zone-types";

export function formatBytes(bytes: number) {
  if (bytes < 1000) return `${bytes} B`;
  const unit = bytes < 1e6 ? "KB" : bytes < 1e9 ? "MB" : "GB";
  const value = bytes / (unit === "KB" ? 1000 : unit === "MB" ? 1e6 : 1e9);
  return `${Number(value.toFixed(1))} ${unit}`;
}

export const acceptRules = (accept = "") =>
  accept
    .split(",")
    .map((rule) => rule.trim().toLowerCase())
    .filter(Boolean);

export function acceptsFile(file: File, rules: string[]) {
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return (
    !rules.length ||
    rules.some((rule) =>
      rule.startsWith(".")
        ? name.endsWith(rule)
        : rule.endsWith("/*")
          ? type.startsWith(rule.slice(0, -1))
          : type === rule,
    )
  );
}

export const sameFile = (a: File, b: File) =>
  a.name === b.name &&
  a.size === b.size &&
  a.type === b.type &&
  a.lastModified === b.lastModified;

export function selectionHint(
  accept?: string,
  maxSize?: number,
  maxFiles?: number,
) {
  const types = acceptRules(accept)
    .map((rule) =>
      rule.startsWith(".")
        ? rule.slice(1).toUpperCase()
        : rule.endsWith("/*")
          ? `${rule.slice(0, -2)} files`
          : rule.split("/").pop(),
    )
    .join(", ");
  return [
    types || "Any file type",
    maxSize === undefined ? "" : `Up to ${formatBytes(maxSize)} per file`,
    maxFiles === undefined
      ? ""
      : `${maxFiles} file${maxFiles === 1 ? "" : "s"} maximum`,
  ]
    .filter(Boolean)
    .join(" · ");
}

/** Validate a whole batch before replacing a single-file selection. */
export function selectFiles(
  files: File[],
  current: File[],
  options: {
    accept?: string;
    maxSize?: number;
    maxFiles?: number;
    multiple?: boolean;
  },
) {
  const { maxSize, maxFiles, multiple = true } = options;
  const rules = acceptRules(options.accept);
  const limit =
    maxFiles === undefined ? Infinity : Math.max(0, Math.floor(maxFiles));
  const room = multiple
    ? Math.max(0, limit - current.length)
    : Math.min(1, limit);
  const accepted: File[] = [];
  const rejected: DropZoneRejection[] = [];
  for (const file of files) {
    let problem: Omit<DropZoneRejection, "file"> | undefined;
    if (!acceptsFile(file, rules))
      problem = { code: "type", reason: "This file type is not supported." };
    else if (maxSize !== undefined && file.size > maxSize)
      problem = {
        code: "size",
        reason: `Exceeds the ${formatBytes(maxSize)} limit.`,
      };
    else if ([...current, ...accepted].some((other) => sameFile(file, other)))
      problem = {
        code: "duplicate",
        reason: "This file has already been added.",
      };
    else if (accepted.length >= room)
      problem = {
        code: "count",
        reason: multiple
          ? `You can add up to ${maxFiles} files.`
          : "Choose one file at a time.",
      };
    if (problem) rejected.push({ file, ...problem });
    else accepted.push(file);
  }
  return { accepted, rejected };
}

"use client";

import { CircleAlert } from "lucide-react";
import type { DropZoneStatus } from "./drop-zone-types";
import {
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/** The original row's progress ring and drawn check, without any flying-file effects. */
export function DropZoneStatusMark({
  status,
  progress,
}: {
  status: DropZoneStatus;
  progress: number;
}) {
  const reduced = useInteractionReducedMotion();
  return (
    <span aria-hidden="true" className="relative ml-1 size-4 shrink-0">
      <svg
        viewBox="0 0 16 16"
        className="absolute inset-0 size-4 -rotate-90"
        style={interactionIcon(status === "uploading", reduced)}
      >
        <circle
          cx="8"
          cy="8"
          r="6"
          fill="none"
          stroke="var(--border)"
          strokeWidth="1.5"
        />
        <circle
          cx="8"
          cy="8"
          r="6"
          fill="none"
          stroke="var(--primary)"
          strokeWidth="1.5"
          strokeLinecap="round"
          pathLength={1}
          strokeDasharray="1"
          strokeDashoffset={1 - progress}
          style={{
            transition: reduced ? "none" : "stroke-dashoffset 200ms ease-out",
          }}
        />
      </svg>
      <svg
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="absolute inset-0 size-4 text-primary"
        style={interactionIcon(status === "done", reduced)}
      >
        <path
          d="M3.5 8.5l3 3 6-7"
          pathLength={1}
          strokeDasharray="1"
          strokeDashoffset={status === "done" ? 0 : 1}
          style={{
            transition: reduced ? "none" : "stroke-dashoffset 260ms ease-out",
          }}
        />
      </svg>
      <span
        className="absolute inset-0 flex items-center justify-center text-red-600 dark:text-red-400"
        style={interactionIcon(status === "error", reduced)}
      >
        <CircleAlert className="size-4" strokeWidth={1.75} />
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import type {
  DropZoneFile,
  DropZoneProps,
  DropZoneRejection,
} from "./drop-zone-types";
import { selectFiles } from "./drop-zone-utils";

type Options = Pick<
  DropZoneProps,
  | "accept"
  | "maxSize"
  | "maxFiles"
  | "multiple"
  | "disabled"
  | "onUpload"
  | "onFilesChange"
  | "onFilesRejected"
>;

export function useDropZone(options: Options) {
  const [rows, setRows] = React.useState<DropZoneFile[]>([]);
  const [rejections, setRejections] = React.useState<DropZoneRejection[]>([]);
  const [announcement, setAnnouncement] = React.useState("");
  const current = React.useRef(rows);
  const latest = React.useRef(options);
  React.useLayoutEffect(() => {
    latest.current = options;
  });
  const controllers = React.useRef(new Map<string, AbortController>());
  const sequence = React.useRef(0);
  const prefix = React.useId();
  const mounted = React.useRef(true);

  React.useEffect(() => {
    mounted.current = true;
    const active = controllers.current;
    return () => {
      mounted.current = false;
      active.forEach((controller) => controller.abort());
      active.clear();
    };
  }, []);

  const commit = React.useCallback((next: DropZoneFile[]) => {
    current.current = next;
    if (mounted.current) setRows(next);
  }, []);

  const patch = React.useCallback(
    (id: string, next: Partial<DropZoneFile>) => {
      if (mounted.current)
        commit(
          current.current.map((row) =>
            row.id === id ? { ...row, ...next } : row,
          ),
        );
    },
    [commit],
  );

  const start = React.useCallback(
    (id: string, file: File) => {
      const upload = latest.current.onUpload;
      if (!upload) {
        patch(id, { status: "ready", progress: 0, error: undefined });
        return;
      }
      controllers.current.get(id)?.abort();
      const controller = new AbortController();
      controllers.current.set(id, controller);
      patch(id, { status: "uploading", progress: 0, error: undefined });
      const active = () =>
        mounted.current &&
        !controller.signal.aborted &&
        controllers.current.get(id) === controller;
      let last = 0;
      Promise.resolve()
        .then(() => {
          if (!active()) return;
          return upload(file, {
            signal: controller.signal,
            progress: (fraction) => {
              if (!active() || !Number.isFinite(fraction)) return;
              const value = Math.max(last, Math.min(1, Math.max(0, fraction)));
              if (value === last) return;
              last = value;
              patch(id, { progress: value });
            },
          });
        })
        .then(
          () => {
            if (!active()) return;
            patch(id, { status: "done", progress: 1 });
            setAnnouncement(`${file.name} uploaded.`);
          },
          (error: unknown) => {
            if (!active()) return;
            const message =
              error instanceof Error && error.message
                ? error.message
                : "Upload failed. Please try again.";
            patch(id, { status: "error", error: message });
            setAnnouncement(`${file.name}: ${message}`);
          },
        )
        .finally(() => {
          if (controllers.current.get(id) === controller)
            controllers.current.delete(id);
        });
    },
    [patch],
  );

  const add = React.useCallback(
    (files: File[]) => {
      const settings = latest.current;
      if (settings.disabled || !files.length) return;
      const { accepted, rejected } = selectFiles(
        files,
        current.current.map((row) => row.file),
        settings,
      );
      setRejections(rejected);
      if (accepted.length) {
        const added: DropZoneFile[] = accepted.map((file) => ({
          id: `${prefix}-${++sequence.current}`,
          file,
          status: settings.onUpload ? "uploading" : "ready",
          progress: 0,
        }));
        if (settings.multiple === false) {
          controllers.current.forEach((controller) => controller.abort());
          controllers.current.clear();
        }
        const next = [
          ...(settings.multiple === false ? [] : current.current),
          ...added,
        ];
        commit(next);
        added.forEach((row) => start(row.id, row.file));
        settings.onFilesChange?.(next.map((row) => row.file));
      }
      setAnnouncement(
        [
          accepted.length
            ? `Added ${accepted.map((file) => file.name).join(", ")}.`
            : "",
          rejected.length
            ? `${rejected.length} file${rejected.length === 1 ? "" : "s"} skipped. Check the file requirements.`
            : "",
        ]
          .filter(Boolean)
          .join(" "),
      );
      if (rejected.length) settings.onFilesRejected?.(rejected);
    },
    [commit, prefix, start],
  );

  const remove = React.useCallback(
    (id: string) => {
      if (latest.current.disabled) return;
      const row = current.current.find((entry) => entry.id === id);
      if (!row) return;
      controllers.current.get(id)?.abort();
      controllers.current.delete(id);
      const next = current.current.filter((entry) => entry.id !== id);
      commit(next);
      setAnnouncement(
        `${row.file.name} ${row.status === "uploading" ? "cancelled" : "removed"}.`,
      );
      latest.current.onFilesChange?.(next.map((entry) => entry.file));
    },
    [commit],
  );

  const retry = React.useCallback(
    (id: string) => {
      if (latest.current.disabled) return;
      const row = current.current.find((entry) => entry.id === id);
      if (row?.status === "error") {
        start(id, row.file);
        setAnnouncement(`Retrying ${row.file.name}.`);
      }
    },
    [start],
  );

  return {
    rows,
    rejections,
    announcement,
    add,
    remove,
    retry,
    dismissRejections: () => setRejections([]),
  };
}

